async function api(action:string,data:Row){const res=await fetch('/api/tms',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action,data})});const result=await res.json() as Row;if(!res.ok)throw new Error(result.error);return result;}
function Field({label,name,value,onChange,type='text',required=false,list,step,min}: {label:string;name:string;value:any;onChange:(name:string,value:any)=>void;type?:string;required?:boolean;list?:string;step?:string;min?:string}){return <label className="field"><span>{label}{required&&' *'}</span><input name={name} type={type} value={value??''} onChange={e=>onChange(name,e.target.value)} required={required} list={list} step={step} min={min}/></label>}
function Select({label,value,onChange,options}:{label:string;value:string;onChange:(v:string)=>void;options:[string,string][]}){return <label className="field"><span>{label}</span><select value={value} onChange={e=>onChange(e.target.value)}>{options.map(([v,l])=><option key={v} value={v}>{l}</option>)}</select></label>}
function Dialog({title,children,close}:{title:string;children:ReactNode;close:()=>void}){useEffect(()=>{const key=(e:KeyboardEvent)=>{if(e.key==='Escape')close();};document.addEventListener('keydown',key);return()=>document.removeEventListener('keydown',key);},[close]);return <div className="overlay" onMouseDown={e=>{if(e.target===e.currentTarget)close();}}><section className="dialog" role="dialog" aria-modal="true" aria-label={title}><header><h2>{title}</h2><button className="icon" onClick={close} aria-label="Close dialog"><X size={20}/></button></header>{children}</section></div>}
type Column={key:string;label:string;render?:(r:Row)=>ReactNode;value?:(r:Row)=>string|number};
function Table({rows,columns,empty='No records yet.'}:{rows:Row[];columns:Column[];empty?:string}){
  if(!rows.length)return <div className="empty"><Package size={28}/><p>{empty}</p><span>Records you add will appear here.</span></div>;
  return <div className="table-scroll"><SortableTable initialSort={{column:0,direction:-1}}><thead><tr>{columns.map(c=><th key={c.key}>{c.label}</th>)}</tr></thead><tbody>{rows.map((r,i)=><tr key={r.id||i}>{columns.map(c=><td key={c.key} data-sort-value={c.value?c.value(r):['string','number','boolean'].includes(typeof r[c.key])?r[c.key]:undefined}>{c.render?c.render(r):String(r[c.key]??'—')}</td>)}</tr>)}</tbody></SortableTable></div>;
}
function download(blob:Blob,name:string){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),10000);}

