  const [entry,setEntry]=useState<Row>(emptyConsignment()),[editing,setEditing]=useState<Row|null>(null),[invoice,setInvoice]=useState<Row|null>(null),[confirm,setConfirm]=useState<{message:string;action:string;data:Row}|null>(null);
  const [selected,setSelected]=useState<string[]>([]),[filters,setFilters]=useState<Row>({}),[profile,setProfile]=useState<Row>({}),[email,setEmail]=useState(''),[memberPassword,setMemberPassword]=useState(''),[resetMember,setResetMember]=useState<Row|null>(null),[passwords,setPasswords]=useState({current:'',next:'',confirm:''}),[importRows,setImportRows]=useState<Row[]|null>(null);
