  async function refresh(targetYear=year){const sequence=++refreshSequence.current;setLoading(true);try{const r=await fetch(`/api/tms?year=${encodeURIComponent(targetYear)}`);if(r.status===401){window.location.replace('/');return;}const s=await r.json() as Row;if(!r.ok)throw new Error(s.error);if(sequence!==refreshSequence.current||targetYear!==activeYear.current)return;if(workspaceId.current&&workspaceId.current!==s.business?.id){window.location.replace('/');return;}workspaceId.current=s.business?.id||null;setState(s);if(!profileDirty.current)setProfile(s.business?.profile||{});}catch(e){setError((e as Error).message);}finally{setLoading(false);}}
  async function logout(){setBusy(true);try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'logout'})});if(!r.ok)throw new Error('Unable to sign out. Please try again.');window.location.replace('/');}catch(e){setError((e as Error).message);setBusy(false);}}
  async function changePassword(event:FormEvent){event.preventDefault();if(passwords.next!==passwords.confirm){setError('New passwords do not match.');return;}setBusy(true);setError('');try{const r=await fetch('/api/auth',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({action:'password.change',currentPassword:passwords.current,password:passwords.next})});const result=await r.json() as Row;if(!r.ok)throw new Error(result.error);setPasswords({current:'',next:'',confirm:''});setNotice('Password changed. Other sessions have been signed out.');}catch(e){setError((e as Error).message);}finally{setBusy(false);}}
  useEffect(()=>{refresh(year);},[year,workspaceRevision]);
  useEffect(()=>{setSelected([]);setFilters(requestedInvoice.current?.year===year?{cn:String(requestedInvoice.current.number)}:{});requestedInvoice.current=null;},[year]);
  async function run(action:string,data:Row,message='Saved successfully.'){setBusy(true);setError('');try{const result=await api(action,{...data,year});setNotice(message);await refresh();return result;}catch(e){setError((e as Error).message);return null;}finally{setBusy(false);}}
  function navigate(next:string){setTab(next);setMenuOpen(false);setFilters({});setSelected([]);setNotice('');setError('');}
  const consignments:Row[]=state?.consignments||[],invoices:Row[]=state?.invoices||[],companies:Row[]=state?.companies||[];
