  const activeSection=workspaceSections.find(s=>s.pages.includes(tab))||workspaceSections[0];
  const workspaceMetrics: [string,string][] = ['ledger','payments'].includes(tab)?[['Provider cost',rupees(filtered.reduce((n,r)=>n+r.truck_freight+r.other_charges,0))],['Recorded paid',rupees(sum(filtered,'provider_total_paid'))],['Remaining',rupees(filtered.reduce((n,r)=>n+paymentDue(r),0))]]:[];
