  {tab==='generate'&&<section className="card">{filterBar()}<div className="table-toolbar"><span>{selected.length} consignments selected</span><button className="primary" disabled={busy||!selected.length} onClick={()=>openInvoice()}><FileText size={16}/> Review invoice</button></div><Table rows={filtered.filter(r=>!r.invoice_id)} empty="No unbilled consignments for these filters." columns={[{key:'select',label:'Select',render:r=><input aria-label={`Select consignment ${r.cn}`} type="checkbox" checked={selected.includes(r.id)} onChange={e=>setSelected(s=>e.target.checked?[...s,r.id]:s.filter(id=>id!==r.id))}/>},...compactCnColumns.filter(c=>c.key!=='invoice_number'),cnColumns[8]]}/></section>}
  {tab==='consignments'&&<section className="card">{filterBar()}<Table rows={filtered} columns={[...compactCnColumns,{key:'stage_status',label:'Status',render:r=><button className="row-action-link" onClick={()=>{setTimelineId(r.id);navigate('timeline');}}>{stageLabels[r.stage_status]||'Status not recorded'}</button>},{key:'actions',label:'Actions',render:r=><div className="inline"><button className="icon" title="Edit consignment" aria-label={`Edit consignment ${r.cn}`} disabled={!!r.invoice_id} onClick={()=>setEditing({...r,rate:r.rate_label||r.rate/100,freight:r.freight/100,advance:r.advance/100})}><Pencil size={16}/></button><button className="icon danger" title="Delete consignment" aria-label={`Delete consignment ${r.cn}`} disabled={!!r.invoice_id} onClick={()=>setConfirm({message:`Delete consignment ${r.cn}? This cannot be undone.`,action:'consignment.delete',data:{id:r.id}})}><Trash2 size={16}/></button></div>}]}/></section>}
  {['invoices','outstanding'].includes(tab)&&<section className="card">{filterBar(true)}<div className="table-toolbar"><span>{filteredInvoices.length} invoices</span></div><Table rows={filteredInvoices} columns={invoiceColumns}/></section>}
  {['payments','ledger'].includes(tab)&&<><section className="card"><button className="small" onClick={()=>navigate('suppliers')}>Supplier directory</button>{filterBar()}<div className="table-toolbar"><span>{filtered.length} consignments</span><span>Open a record to update costs or payments.</span></div><Table rows={filtered} columns={[compactCnColumns[0],{key:'provider',label:'Provider',render:r=><div className="cell-stack"><span className="cell-text">{r.provider||'Not entered'}</span><small>{r.truck}</small></div>},{key:'cost',label:'Total cost',value:r=>r.truck_freight+r.other_charges,render:r=>rupees(r.truck_freight+r.other_charges)},{key:'provider_total_paid',label:'Recorded paid',render:r=>rupees(r.provider_total_paid)},{key:'remaining',label:'Remaining',value:paymentDue,render:r=><div className="cell-stack">{r.provider_total_paid>r.truck_freight+r.other_charges?<strong className="amber">Excess {rupees(r.provider_total_paid-r.truck_freight-r.other_charges)}</strong>:<strong>{rupees(paymentDue(r))}</strong>}<small>{r.provider_due_date?'Due '+r.provider_due_date:'Due date not set'}</small></div>},{key:'payment_status',label:'Status',render:r=><span className={`badge ${r.truck_freight+r.other_charges>0&&!paymentDue(r)?'success':'warning'}`}>{!r.truck_freight&&!r.other_charges?'Cost missing':r.provider_total_paid>r.truck_freight+r.other_charges?'Review excess':!paymentDue(r)?'Paid':r.provider_total_paid?'Part paid':'Unpaid'}</span>},{key:'actions',label:'Payments',render:r=><button className="small" onClick={()=>setSupplierId(r.id)}>View payments</button>}]}/></section><details className="context-notes"><summary>Ageing by provider</summary><SupplierSummary rows={filtered}/></details></>}
  {tab==='search'&&<section className="card">{filterBar()}<div className="filters"><Field label="From (place)" name="origin" value={filters.origin} onChange={(n,v)=>setFilters(f=>({...f,[n]:v}))}/><Field label="To (place)" name="destination" value={filters.destination} onChange={(n,v)=>setFilters(f=>({...f,[n]:v}))}/></div><div className="table-toolbar"><span>{filtered.length} matching consignments</span></div><Table rows={filtered} columns={cnColumns}/></section>}
  {tab==='pnl'&&owner&&<section className="card">{filterBar()}<div className="table-toolbar"><span>Recorded margin = freight − provider freight − provider other charges</span><strong>{rupees(sum(filtered,'freight')-sum(filtered,'truck_freight')-sum(filtered,'other_charges'))}</strong></div><p className="help">{filtered.filter(r=>!r.truck_freight).length} consignments have no provider freight recorded. Margins are provisional. Additional direct expenses and company overheads appear in Company P&amp;L.</p><Table rows={filtered} columns={[...cnColumns.slice(0,6),{key:'freight',label:'Customer freight',render:r=>rupees(r.freight)},{key:'truck_freight',label:'Provider freight',render:r=>r.truck_freight?rupees(r.truck_freight):'Not recorded'},{key:'other_charges',label:'Provider other charges',render:r=>rupees(r.other_charges)},{key:'profit',label:'Recorded margin',value:r=>r.freight-r.truck_freight-r.other_charges,render:r=><strong>{rupees(r.freight-r.truck_freight-r.other_charges)}</strong>}]}/></section>}
