  {editAccess&&<Dialog title={`Team access · ${editAccess.email}`} close={()=>setEditAccess(null)}><form onSubmit={async e=>{e.preventDefault();if(await run('team.role',{id:editAccess.user_id,expectedRole:editAccess.role,role:editAccess.nextRole},'Team access updated. This member must sign in again.'))setEditAccess(null);}}><Select label="Account role" value={editAccess.nextRole} onChange={v=>setEditAccess(r=>({...r,nextRole:v}))} options={[["DISPATCHER","Dispatcher"],["MEMBER","Commercial member"]]}/><p className="help">Dispatcher: workspace consignments and trip planning/progress, with commercial amounts omitted. Commercial member: existing access including freight, invoices and supplier costs. Access changes are recorded and sign out this member's sessions.</p><footer className="form-footer"><button type="button" className="small" onClick={()=>setEditAccess(null)}>Cancel</button><button className="primary" disabled={busy||editAccess.nextRole===editAccess.role}>Save access</button></footer></form></Dialog>}{resetMember&&<Dialog title={`Reset password · ${resetMember.email}`} close={()=>setResetMember(null)}><form onSubmit={async e=>{e.preventDefault();if(await run('team.password',{id:resetMember.user_id,password:resetMember.password},'Password reset. All sessions for this member have been signed out.'))setResetMember(null);}}><p className="help">Provide the new password securely to this member. No email is sent.</p><Field label="New password (8–128 characters)" type="password" name="password" value={resetMember.password} onChange={(_,v)=>setResetMember(r=>({...r,password:v}))} required/><footer className="form-footer"><span/><button className="primary" disabled={busy}>Reset password</button></footer></form></Dialog>}
